-- INSERT BOOK_COPY DATA
-- Creates 10, 9, or 8 copies per book based on book_id

INSERT INTO BOOK_COPY (book_id, status, condition, barcode)
SELECT 
  book_id,
  'in_stock',
  'new',
  'BC_' || book_id || '_' || copy_num AS barcode
FROM (
  SELECT 1 as book_id, 1 as copy_num UNION ALL SELECT 1, 2 UNION ALL SELECT 1, 3 UNION ALL SELECT 1, 4 UNION ALL SELECT 1, 5 UNION ALL SELECT 1, 6 UNION ALL SELECT 1, 7 UNION ALL SELECT 1, 8 UNION ALL SELECT 1, 9 UNION ALL SELECT 1, 10 UNION ALL
  SELECT 2, 1 UNION ALL SELECT 2, 2 UNION ALL SELECT 2, 3 UNION ALL SELECT 2, 4 UNION ALL SELECT 2, 5 UNION ALL SELECT 2, 6 UNION ALL SELECT 2, 7 UNION ALL SELECT 2, 8 UNION ALL SELECT 2, 9 UNION ALL SELECT 2, 10 UNION ALL
  SELECT 3, 1 UNION ALL SELECT 3, 2 UNION ALL SELECT 3, 3 UNION ALL SELECT 3, 4 UNION ALL SELECT 3, 5 UNION ALL SELECT 3, 6 UNION ALL SELECT 3, 7 UNION ALL SELECT 3, 8 UNION ALL SELECT 3, 9 UNION ALL SELECT 3, 10 UNION ALL
  SELECT 4, 1 UNION ALL SELECT 4, 2 UNION ALL SELECT 4, 3 UNION ALL SELECT 4, 4 UNION ALL SELECT 4, 5 UNION ALL SELECT 4, 6 UNION ALL SELECT 4, 7 UNION ALL SELECT 4, 8 UNION ALL SELECT 4, 9 UNION ALL SELECT 4, 10 UNION ALL
  SELECT 5, 1 UNION ALL SELECT 5, 2 UNION ALL SELECT 5, 3 UNION ALL SELECT 5, 4 UNION ALL SELECT 5, 5 UNION ALL SELECT 5, 6 UNION ALL SELECT 5, 7 UNION ALL SELECT 5, 8 UNION ALL SELECT 5, 9 UNION ALL
  SELECT 6, 1 UNION ALL SELECT 6, 2 UNION ALL SELECT 6, 3 UNION ALL SELECT 6, 4 UNION ALL SELECT 6, 5 UNION ALL SELECT 6, 6 UNION ALL SELECT 6, 7 UNION ALL SELECT 6, 8 UNION ALL SELECT 6, 9 UNION ALL
  SELECT 7, 1 UNION ALL SELECT 7, 2 UNION ALL SELECT 7, 3 UNION ALL SELECT 7, 4 UNION ALL SELECT 7, 5 UNION ALL SELECT 7, 6 UNION ALL SELECT 7, 7 UNION ALL SELECT 7, 8 UNION ALL SELECT 7, 9 UNION ALL
  SELECT 8, 1 UNION ALL SELECT 8, 2 UNION ALL SELECT 8, 3 UNION ALL SELECT 8, 4 UNION ALL SELECT 8, 5 UNION ALL SELECT 8, 6 UNION ALL SELECT 8, 7 UNION ALL SELECT 8, 8 UNION ALL
  SELECT 9, 1 UNION ALL SELECT 9, 2 UNION ALL SELECT 9, 3 UNION ALL SELECT 9, 4 UNION ALL SELECT 9, 5 UNION ALL SELECT 9, 6 UNION ALL SELECT 9, 7 UNION ALL SELECT 9, 8 UNION ALL
  SELECT 10, 1 UNION ALL SELECT 10, 2 UNION ALL SELECT 10, 3 UNION ALL SELECT 10, 4 UNION ALL SELECT 10, 5 UNION ALL SELECT 10, 6 UNION ALL SELECT 10, 7 UNION ALL SELECT 10, 8
) data;